<template><view class="hierarchy-page"><NativeStatusSpacer/><view class="header"><button @tap="back">‹</button><text>{{creating?'新增组织节点':'组织层级浏览'}}</text></view><text v-if="error" class="error">{{error}}</text><text v-if="busy">正在加载</text><template v-else-if="allowed"><view class="breadcrumbs"><template v-for="(node,index) in ancestors" :key="node.id"><text v-if="index" class="crumb-arrow">›</text><text class="crumb" @tap="enter(node)">{{node.name}}</text></template><text v-if="!ancestors.length">选择管理机构</text></view><view class="path"><view class="node-icon"><PrototypeIcon :name="current?.typeCode==='CLASS'?'people':'school'" :size="42"/></view><text>{{current?.name||'选择管理机构'}}</text><button v-if="current?.parentId" @tap="up">上一级</button></view><view v-if="creating" class="card"><view v-if="types.length>1" class="node-type-tabs"><button v-for="(item,index) in types" :key="item" :class="{active:typeIndex===index}" :disabled="saving" @tap="selectNodeType(index)">{{typeLabels[index]}}</button></view><text class="form-label">{{typeLabels[typeIndex]||'组织'}}名称 <text class="required">*</text></text><input :disabled="saving" v-model="name" placeholder="组织名称" maxlength="64"/><template v-if="types[typeIndex]==='CATEGORY'||(training&&types[typeIndex]==='GRADE')"><text class="form-label">学段适用 *</text><text v-if="!courseOptions.configured" class="error">{{courseOptionsError||'学段和学科字典尚未配置，请联系管理员'}}</text><checkbox-group @change="stageCodes=$event.detail.value"><label v-for="stage in courseOptions.stages" :key="stage.code"><checkbox :value="stage.code" :checked="stageCodes.includes(stage.code)" :disabled="saving"/>{{stage.name}}</label></checkbox-group><text class="form-label">学科类型 *</text><picker :disabled="saving" :range="courseOptions.subjects" range-key="name" :value="subjectIndex" @change="subjectIndex=Number($event.detail.value)"><view class="field">{{courseOptions.subjects[subjectIndex]?.name||'请选择学科'}}</view></picker><text class="form-label">分类描述</text><textarea v-model="description" :disabled="saving" maxlength="100" placeholder="请输入分类描述（可选）"/><text class="description-count">{{description.length}}/100</text></template><text class="form-label">排序</text><input :disabled="saving" v-model="sort" type="number" placeholder="排序（非负整数）"/><button class="node-save" :disabled="saving" @tap="save">{{saving?'保存中':'保存'}}</button><button :disabled="saving" @tap="creating=false;editingId=''">取消</button></view><template v-else><view v-for="row in treeRows" :key="row.node.id" class="row" :class="{'campus-row':row.node.typeCode==='CAMPUS','grade-row':row.node.typeCode==='GRADE','hierarchy-class-row':row.node.typeCode==='CLASS'}" :style="{marginLeft:(row.depth*24)+'rpx'}" @tap="toggleTreeNode(row.node,row.hasChildren)"><text class="tree-toggle">{{row.hasChildren?(expandedNodes.includes(row.node.id)?'⌄':'›'):''}}</text><view class="node-icon"><PrototypeIcon :name="row.node.typeCode==='CLASS'?'people':'school'" :size="34"/></view><view class="node-copy"><text class="name">{{row.node.name}}</text><text v-if="row.node.typeCode==='CLASS'" class="member-badge">{{classCounts[row.node.id]??0}}人</text><text v-if="row.node.typeCode!=='CLASS'" class="meta">{{nodeSummary(row.node)}}</text><text v-if="row.node.status!=='ENABLED'" class="node-disabled">停用</text></view><button class="tree-enter" :aria-label="'进入'+row.node.name" @tap.stop="enter(row.node)">›</button></view><text v-if="!visible.length" class="empty">暂无下级组织</text><button v-if="canCreate&&types.length&&current?.effectiveStatus==='ENABLED'" @tap="openCreate">＋ 新增{{typeLabels.join(' / ')}}</button><button v-if="training&&current?.typeCode==='GRADE'&&canUpdate&&current.effectiveStatus==='ENABLED'" @tap="editCategory">编辑课程分类</button><button v-if="current?.typeCode==='GRADE'||current?.typeCode==='CLASS'" @tap="classes">进入班级管理</button></template></template></view></template>
<script setup lang="ts">
import {courseCategoryApi,type CourseCategoryOptions} from '@/api/organization-hierarchy';
import {hierarchyTreeRows,hierarchyNodeSummary} from '@/models/hierarchy-tree';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import {classDetailRoute} from '@/models/class-detail';
import {ref,computed} from 'vue';import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import {hierarchyApi,childTypes,type HierarchyNode} from '@/api/organization-hierarchy';import {getOrganizationSession} from '@/session/organization-session';
const nodes=ref<HierarchyNode[]>([]),current=ref<HierarchyNode|null>(null),allowed=ref(false),canCreate=ref(false),busy=ref(false),saving=ref(false),creating=ref(false),error=ref(''),name=ref(''),code=ref(''),sort=ref('0'),typeIndex=ref(0);let epoch=0;
const editingId=ref(''),editingVersion=ref(0),canUpdate=ref(false);
const courseOptionsError=ref('');
const courseOptions=ref<CourseCategoryOptions>({configured:false,stages:[],subjects:[]}),stageCodes=ref<string[]>([]),subjectIndex=ref(-1),description=ref('');
const labels:Record<string,string>={SCHOOL:'学校',TRAINING_INSTITUTION:'培训机构',CAMPUS:'校区',GRADE:'年级',CLASS:'班级'};const training=computed(()=>{let node=current.value;const seen=new Set<string>();while(node&&!seen.has(node.id)){seen.add(node.id);if(node.typeCode==='TRAINING_INSTITUTION')return true;node=nodes.value.find(n=>n.id===node?.parentId)||null;}return false;});function label(t:string){return t==='CATEGORY'?'课程分类':training.value&&t==='GRADE'?'课程分类':training.value&&t==='CLASS'?'课程班':labels[t]||t;}const types=computed(()=>editingId.value?['GRADE']:(current.value&&['SCHOOL','TRAINING_INSTITUTION'].includes(current.value.typeCode)?(training.value?['CAMPUS','GRADE']:['CAMPUS','GRADE','CATEGORY']):childTypes(current.value?.typeCode||''))),typeLabels=computed(()=>types.value.map(label));const visible=computed(()=>(current.value?nodes.value.filter(n=>n.parentId===current.value?.id):nodes.value.filter(n=>['SCHOOL','TRAINING_INSTITUTION'].includes(n.typeCode))).sort((a,b)=>(a.sortOrder??0)-(b.sortOrder??0)||a.name.localeCompare(b.name,'zh-CN')||a.id.localeCompare(b.id)));
function nodeSummary(node:HierarchyNode){return hierarchyNodeSummary(nodes.value,node);}
const expandedNodes=ref<string[]>([]);const classCounts=ref<Record<string,number>>({});
const treeRows=computed(()=>current.value?hierarchyTreeRows(nodes.value,current.value.id,expandedNodes.value):visible.value.map(node=>({node,depth:0,hasChildren:nodes.value.some(child=>child.parentId===node.id)})));
function toggleTreeNode(node:HierarchyNode,hasChildren:boolean){if(saving.value)return;if(!current.value||!hasChildren){enter(node);return;}expandedNodes.value=expandedNodes.value.includes(node.id)?expandedNodes.value.filter(id=>id!==node.id):[...expandedNodes.value,node.id];}
const ancestors=computed(()=>{const result:HierarchyNode[]=[];let node=current.value;const seen=new Set<string>();while(node&&!seen.has(node.id)){seen.add(node.id);result.unshift(node);node=nodes.value.find(item=>item.id===node?.parentId)||null;}return result;});
function flatten(rows:HierarchyNode[]):HierarchyNode[]{return rows.flatMap(n=>[n,...flatten(n.children||[])]);}function enter(n:HierarchyNode){if(saving.value)return;if(n.typeCode==='CLASS'){uni.navigateTo({url:classDetailRoute(n.id)});return;}current.value=n;creating.value=false;editingId.value='';typeIndex.value=0;}function up(){if(saving.value)return;current.value=nodes.value.find(n=>n.id===current.value?.parentId)||null;}function back(){if(saving.value)return;if(creating.value){creating.value=false;editingId.value='';}else uni.navigateBack();}function classes(){uni.navigateTo({url:'/pages/organization-classes/organization-classes'});}
function openCreate(){if(saving.value||!canCreate.value||!types.value.length||current.value?.effectiveStatus!=='ENABLED')return;editingId.value='';editingVersion.value=0;name.value='';code.value='';sort.value='0';stageCodes.value=[];subjectIndex.value=-1;description.value='';typeIndex.value=0;error.value='';creating.value=true;}
function selectNodeType(index:number){if(saving.value||!Number.isInteger(index)||index<0||index>=types.value.length)return;typeIndex.value=index;error.value='';}
function hierarchyScope(){const selected=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string}|undefined;return `${selected?.accessToken||''}|${selected?.organizationId||''}`;}
async function load(retainId?:string){const n=++epoch,t=getOrganizationSession()?.accessToken,scope=hierarchyScope();nodes.value=[];current.value=null;allowed.value=false;canCreate.value=false;error.value='';courseOptionsError.value='';busy.value=true;try{if(!t)throw Error('请先登录');const me=await hierarchyApi.me(t);if(scope!==hierarchyScope()||n!==epoch)return;if(!me.permissionCodes.includes('CLASS_READ'))throw Error('没有组织查看权限');const [tree,counts]=await Promise.all([hierarchyApi.tree(t),hierarchyApi.studentCounts(t).catch(()=>[] as {organizationId:string;memberCount:number}[])]);const opts=await courseCategoryApi.options(t).catch(()=>{if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t)courseOptionsError.value='学段和学科选项加载失败，请重新进入后重试';return {configured:false,stages:[],subjects:[]} as CourseCategoryOptions;});if(scope!==hierarchyScope()||n!==epoch||getOrganizationSession()?.accessToken!==t)return;courseOptions.value=opts;if(scope!==hierarchyScope()||n!==epoch||getOrganizationSession()?.accessToken!==t)return;nodes.value=flatten(tree);const countMap:Record<string,number>={};for(const item of counts)countMap[item.organizationId]=item.memberCount;classCounts.value=countMap;allowed.value=true;canCreate.value=me.permissionCodes.includes('CLASS_CREATE');canUpdate.value=me.permissionCodes.includes('CLASS_UPDATE');const selection=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};if(selection?.accessToken===t&&selection.organizationId){const selected=nodes.value.find(row=>row.id===selection.organizationId);if(!selected)throw Error('当前组织不在可管理范围');current.value=selected;}if(retainId)current.value=nodes.value.find(row=>row.id===retainId)||current.value;}catch(e){if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t){allowed.value=false;error.value=e instanceof Error?e.message:'加载失败';}}finally{if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t)busy.value=false;}}
async function editCategory(){const t=getOrganizationSession()?.accessToken,node=current.value,n=epoch,scope=hierarchyScope();if(!t||!node||saving.value)return;saving.value=true;try{const data=await courseCategoryApi.read(t,node.id);if(scope!==hierarchyScope()||n!==epoch||getOrganizationSession()?.accessToken!==t)return;editingId.value=node.id;editingVersion.value=node.versionNo||0;name.value=node.name;sort.value=String(node.sortOrder||0);stageCodes.value=data?.stageCodes||[];subjectIndex.value=courseOptions.value.subjects.findIndex(s=>s.code===data?.subjectCode);description.value=data?.description||'';typeIndex.value=0;creating.value=true;}catch(e){if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t)error.value=e instanceof Error?e.message:'加载失败';}finally{if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t)saving.value=false;}}
async function save(){const t=getOrganizationSession()?.accessToken,n=epoch,scope=hierarchyScope();if(saving.value||!t||!current.value||!(editingId.value?canUpdate.value:canCreate.value))return;const type=types.value[typeIndex.value];if(!type||!name.value.trim()||(!/^\d+$/.test(sort.value)||!Number.isSafeInteger(Number(sort.value))||Number(sort.value)>2147483647)){error.value='请填写名称与非负整数排序';return;}let root=current.value;const visited=new Set<string>();while(root.parentId&&!['SCHOOL','TRAINING_INSTITUTION'].includes(root.typeCode)&&!visited.has(root.id)){visited.add(root.id);const parent=nodes.value.find(row=>row.id===root.parentId);if(!parent)break;root=parent;}if(!['SCHOOL','TRAINING_INSTITUTION'].includes(root.typeCode)){error.value='所属机构不可访问';return;}const schoolId=root.id,parentType=current.value.typeCode;const parentId=current.value.id;if((type==='CATEGORY'||(training.value&&type==='GRADE'))&&(!courseOptions.value.configured||!stageCodes.value.length||!courseOptions.value.subjects[subjectIndex.value])){error.value='请选择有效学段和学科';return;}saving.value=true;error.value='';try{if(type==='CATEGORY'||(training.value&&type==='GRADE')){await (editingId.value?courseCategoryApi.update(t,editingId.value,{schoolOrganizationId:schoolId,name:name.value.trim(),sortOrder:Number(sort.value),versionNo:editingVersion.value,metadata:{stageCodes:stageCodes.value,subjectCode:courseOptions.value.subjects[subjectIndex.value].code,description:description.value}}):courseCategoryApi.create(t,{schoolOrganizationId:schoolId,...(parentType==='CAMPUS'?{campusOrganizationId:parentId}:{}),name:name.value.trim(),sortOrder:Number(sort.value),metadata:{stageCodes:stageCodes.value,subjectCode:courseOptions.value.subjects[subjectIndex.value].code,description:description.value}}));}else await hierarchyApi.create(t,{parentId:current.value.id,typeCode:type,name:name.value.trim(),code:code.value.trim(),sortOrder:Number(sort.value),schoolId,parentType});if(scope!==hierarchyScope()||n!==epoch||getOrganizationSession()?.accessToken!==t)return;creating.value=false;editingId.value='';name.value='';code.value='';stageCodes.value=[];description.value='';subjectIndex.value=-1;saving.value=false;await load(parentId);}catch(e){if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t)error.value=e instanceof Error?e.message:'保存失败';}finally{if(n===epoch&&scope===hierarchyScope()&&getOrganizationSession()?.accessToken===t)saving.value=false;}}
function clear(){courseOptionsError.value='';courseOptions.value={configured:false,stages:[],subjects:[]};expandedNodes.value=[];classCounts.value={};epoch++;nodes.value=[];current.value=null;allowed.value=false;creating.value=false;editingId.value='';saving.value=false;}onShow(()=>load());onHide(clear);onUnload(clear);
</script>
<style scoped>.hierarchy-page{padding:24rpx 28rpx;background:#f6f9f5;min-height:100vh;box-sizing:border-box;color:#193e32}.header,.path,.row{display:flex;align-items:center;justify-content:space-between}.header{font-size:32rpx;font-weight:700;margin-bottom:28rpx}.path{padding:22rpx;background:#eaf3e8;border-radius:18rpx;margin-bottom:24rpx}.row{background:white;border-bottom:1rpx solid #e6eee4;padding:28rpx;border-radius:16rpx}.name{font-size:30rpx;font-weight:650}.meta{display:block;color:#7c867d;font-size:23rpx;margin-top:10rpx}.card{background:white;padding:26rpx;border-radius:24rpx}.field,input{padding:20rpx;background:#f8faf6;border:1rpx solid #dfe8dc;border-radius:14rpx;margin-top:22rpx;font-size:26rpx}button{background:#e7f1e4;color:#176a4b;border-radius:16rpx;font-size:26rpx;padding:16rpx;margin-top:20rpx}button::after{border:0}.error{display:block;color:#b05242;margin:20rpx 0}.empty{display:block;padding:28rpx;color:#7d867e}</style>

<style scoped>.breadcrumbs{display:flex;align-items:center;gap:14rpx;overflow-x:auto;white-space:nowrap;font-size:23rpx;color:#215b43;padding:12rpx 0 22rpx}.crumb{flex-shrink:0}.crumb-arrow{color:#8a978d}.node-icon{flex-shrink:0;display:flex;align-items:center;justify-content:center;width:66rpx;height:66rpx;border-radius:14rpx;background:#edf5ef}.row{gap:18rpx;margin-bottom:8rpx;padding:22rpx 20rpx}.node-copy{flex:1;min-width:0}.path{gap:16rpx}.path>text{flex:1}.path button{margin:0;padding:12rpx;font-size:23rpx}.hierarchy-page{min-height:calc(100vh - var(--window-top,0px))}</style>

<style scoped>.form-parent{display:block;padding:18rpx 20rpx;background:#edf5ef;color:#52705e;border-radius:14rpx;font-size:25rpx}.form-label{display:block;font-size:26rpx;font-weight:600;margin-top:30rpx;color:#253b2f}.required{color:#c56b54}.card input,.card .field{margin-top:12rpx;background:#fff}.card .node-save{background:linear-gradient(120deg,#1a7657,#10503f);color:#fff;min-height:84rpx;margin-top:36rpx;border-radius:16rpx;font-size:29rpx}</style>


<style scoped>.tree-toggle{width:22rpx;flex-shrink:0;color:#23664d}.tree-enter{margin:0;padding:0 14rpx;background:transparent;font-size:35rpx}.row{border-radius:0}.row .node-icon{width:48rpx;height:48rpx}.member-badge{flex-shrink:0;margin-left:14rpx;background:#e8f3ed;color:#17664e;border-radius:12rpx;padding:4rpx 14rpx;font-size:22rpx;font-weight:600}.grade-row .member-badge{margin-left:0}</style>


<style scoped>.hierarchy-page{padding-top:0;background:#fff}.header{height:88rpx;box-sizing:border-box;margin:0 -28rpx 12rpx;padding:0 112px;position:relative;justify-content:center;background:#fff;font-size:30rpx}.header>text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.header>button{position:absolute;left:14rpx;top:0;margin:0;padding:0;width:56rpx;height:88rpx;line-height:80rpx;background:transparent;font-size:50rpx}</style>

<style scoped>.node-type-tabs{display:flex;background:#f4f6f4;border-radius:16rpx;padding:4rpx;gap:4rpx;margin-bottom:22rpx}.node-type-tabs button{flex:1;margin:0;background:transparent;font-size:27rpx;padding:15rpx 8rpx;border-radius:12rpx}.node-type-tabs button.active{color:#10583f;background:#e8f3ed;box-shadow:inset 0 -4rpx #17664e;font-weight:650}.card{padding:8rpx 0 24rpx;border-radius:0}.card textarea{box-sizing:border-box;width:100%;height:180rpx;border:1rpx solid #dfe8dc;border-radius:14rpx;padding:18rpx;font-size:26rpx;margin-top:12rpx}.description-count{display:block;text-align:right;font-size:23rpx;color:#86918b;margin-top:8rpx}.card checkbox-group{display:flex;flex-wrap:wrap;gap:24rpx;margin-top:18rpx;font-size:26rpx}.card checkbox-group label{display:flex;align-items:center}</style>


<style scoped>.row.campus-row{border:1rpx solid #e4ebe5;border-radius:18rpx;margin:12rpx 0;padding:16rpx 12rpx}.campus-row .name{font-size:28rpx}.grade-row,.hierarchy-class-row{padding:14rpx 10rpx;min-height:64rpx;box-sizing:border-box}.grade-row .node-copy{display:flex;align-items:center;gap:16rpx;flex-wrap:wrap}.grade-row .meta{margin:0;font-size:24rpx}.grade-row .name,.hierarchy-class-row .name{font-size:26rpx;font-weight:500}.row .tree-enter{font-size:32rpx;line-height:1;padding:8rpx}.row .meta{color:#7d8792}.node-disabled{font-size:22rpx;color:#ac6952;margin-left:10rpx}.hierarchy-class-row .node-icon{background:transparent;width:40rpx;height:40rpx}.path{background:#fff;border-bottom:1rpx solid #e8eeea;border-radius:0;padding:16rpx 0;margin-bottom:10rpx}.path .node-icon{background:#fff8e7;border-radius:12rpx}.path>text{font-size:29rpx;font-weight:650}.breadcrumbs{background:#f5f8f6;margin:0 -28rpx;padding:22rpx 28rpx;box-sizing:border-box}.hierarchy-page{color:#182b25}.header{margin-bottom:0}</style>

